#!/usr/bin/env python3\n"""Static guardrails for critical source invariants. This is not a compiler or integration test."""\nfrom pathlib import Path\nimport sys\nimport xml.etree.ElementTree as ET\n\nROOT = Path(__file__).resolve().parents[1]\nchecks = []\ndef check(name, condition, detail): checks.append((name, bool(condition), detail))\ndef read(rel): return (ROOT / rel).read_text(encoding="utf-8")\n\nauth = read("src/main/java/com/tuempresa/identity/security/AuthFilter.java")\nconfig = read("src/main/resources/application.yml")\nbootstrap = read("src/main/java/com/tuempresa/identity/web/BootstrapController.java")\npayment = read("src/main/java/com/tuempresa/billing/delegate/RegistrarPagoDelegate.java")\nthreeway = read("src/main/java/com/tuempresa/billing/delegate/ThreeWayMatchDelegate.java")\ncompliance = read("src/main/java/com/tuempresa/compliance/delegate/VerificarComplianceDelegate.java")\nbpmn = read("src/main/resources/bpmn/paymentApprovalProcess.bpmn")\noutbox = read("src/main/java/com/tuempresa/platform/events/OutboxPoller.java")\nops = read("src/main/java/com/tuempresa/platform/web/OpsDashboardController.java")\nwebhook = read("src/main/java/com/tuempresa/integration/procore/ProcoreController.java")\n\ncheck("X-User-Id deshabilitado por defecto", '@Value("${construction.auth.allow-user-id:false}")' in auth and 'allow-user-id: ${ALLOW_X_USER_ID:false}' in config,\n      "El bypass solo debe usarse por configuración explícita de dev/test.")\ncheck("Bootstrap requiere secreto y compara en tiempo constante", 'X-Bootstrap-Token' in bootstrap and 'MessageDigest.isEqual' in bootstrap and 'expectedToken.isBlank()' in bootstrap,\n      "Sin secreto, bootstrap debe quedar deshabilitado.")\ncheck("Pago no se marca ejecutado sin proveedor", "'PENDING'" in payment and "SET status = 'EXECUTED'" not in payment and "executed_at" in payment and "NULL, 'PENDING'" in payment,\n      "El delegate crea instrucción pendiente, no transferencia bancaria.")\ncheck("Three-way match cubre proyecto y simetría de líneas", "project_id = ?" in threeway and "invLines.size() != poLines.size()" in threeway and "invoiceLineNumbers.equals(poLineNumbers)" in threeway,\n      "No aceptar PO de otra obra ni líneas omitidas/duplicadas.")\ncheck("Three-way match concilia total de encabezado y líneas", "MISMATCH_FACTURA_TOTAL" in threeway and "invoiceLineTotal" in threeway,\n      "No se registra pago si el total del encabezado no coincide con la suma extendida de líneas.")\ncheck("Match BPMN es fail-closed", 'id="GW_Match" default="F_Match_Fail"' in bpmn and "matchResult.estado == 'MATCH'" in bpmn,\n      "Solo una salida MATCH explícita entra a registrar pago.")\ncheck("Compliance BPMN es fail-closed", 'id="GW_ComplianceDecision" default="F_P2_Blocked"' in bpmn and "complianceValid == true" in bpmn and "requisitos_vigentes" in compliance and "!expiry.isBefore(hoy)" in compliance,\n      "El gate exige estado global, conteos, estado crítico y fecha vigente.")\ncheck("Outbox rechaza handlers desconocidos", 'Tipo outbox sin handler registrado' in outbox and 'default -> throw new IllegalStateException' in outbox,\n      "Un evento sin handler no debe marcarse procesado.")\noutbox_sql = read("src/main/resources/db/migration/V17__hardening_security_outbox_payment.sql")\noutbox_cfg = read("src/main/java/com/tuempresa/platform/events/OutboxDataSourceConfiguration.java")\ncheck("Claim global aislado en credencial de worker", "REVOKE ALL ON FUNCTION claim_projection_outbox(integer) FROM app_user" in outbox_sql and "TO outbox_worker" in outbox_sql and '@Qualifier("outboxJdbcTemplate")' in outbox and 'outboxTransactionManager' in outbox_cfg,\n      "El worker tiene su propio datasource/pool y app_user no recibe permiso de ejecución.")\ncheck("Dashboard limita colas por membresía de obra", "project_membership pm" in ops and "pm.user_id = ?" in ops and "boundedLimit" in ops,\n      "Las métricas/colas no deben ser de todo el tenant para cada usuario.")\ncheck("Webhook Procore no devuelve falso éxito", "HttpStatus.NOT_IMPLEMENTED" in webhook and "deshabilitado" in webhook.lower(),\n      "Inbound permanece cerrado hasta verificación y procesamiento real.")\ncheck("Ofertas no aceptan bidderId no verificado", "HttpStatus.NOT_IMPLEMENTED" in read("src/main/java/com/tuempresa/bidding/web/BiddingController.java") and "vínculo de identidad" in read("src/main/java/com/tuempresa/bidding/web/BiddingController.java"),\n      "Evita atribuir una oferta a un tercero antes de enlazar el usuario con la parte legal.")\ncompose = read("docker-compose.yml")\ngates = read("scripts/verify-gates.sh")\ncheck("Migraciones aisladas del runtime HTTP", 'dockerfile: Dockerfile.migrator' in compose and 'SPRING_FLYWAY_ENABLED: "false"' in compose and 'enabled: ${SPRING_FLYWAY_ENABLED:false}' in config,\n      "La credencial de propietario solo debe estar en el job de migración, nunca en el API.")\ncheck("Camunda aislado de public", "schema-name: camunda" in config and "CREATE SCHEMA IF NOT EXISTS camunda" in read("src/main/resources/db/migration/V20__camunda_schema_isolation.sql") and "REVOKE CREATE ON SCHEMA public FROM app_user" in read("src/main/resources/db/migration/V20__camunda_schema_isolation.sql"),\n      "Las tablas del motor no deben forzar privilegios CREATE amplios sobre public.")\npayment_service = read("src/main/java/com/tuempresa/billing/service/PaymentApplicationService.java")\npayment_controller = read("src/main/java/com/tuempresa/billing/web/PaymentController.java")\ncheck("Solicitud de pago exige idempotencia", 'RequestHeader("Idempotency-Key")' in payment_controller and "submission_idempotency_key" in payment_service and "submission_request_hash" in payment_service,\n      "Los reintentos exactos devuelven el proceso existente y una clave reutilizada con otro payload falla.")\ncheck("Reservas parciales no exceden factura", "pendingApplications.add(reservedPayments).add(amount).compareTo(invoiceAmount)" in payment_service and "FOR UPDA